1	import type { Layout, RegisteredGroup } from "../../components/group/types";
2	import type { PanelConstraints } from "../../components/panel/types";
3	import { EventEmitter } from "../../utils/EventEmitter";
4	import type { SeparatorToPanelsMap } from "./types";
5	
6	type State = {
7	  defaultLayoutDeferred: boolean;
8	  derivedPanelConstraints: PanelConstraints[];
9	  groupSize: number;
10	  layout: Layout;
11	  separatorToPanels: SeparatorToPanelsMap;
12	};
13	
14	export type MountedGroups = Map<RegisteredGroup, State>;
15	
16	let map: MountedGroups = new Map();
17	
18	type GroupChangeEvent = {
19	  group: RegisteredGroup;
20	  // True if the change was triggered by a pointer or keyboard event handler
21	  // False for other types of resize (constraint recompute, default-size change, imperative API, etc.).
22	  isUserInteraction: boolean;
23	  next: State;
24	  prev: State | undefined;
25	};
26	type GroupsChangeEvent = {
27	  next: MountedGroups;
28	  prev: MountedGroups;
29	};
30	
31	const eventEmitter = new EventEmitter<{
32	  groupChange: GroupChangeEvent;
33	  groupsChange: GroupsChangeEvent;
34	}>();
35	
36	export function deleteMutableGroup(group: RegisteredGroup) {
37	  map = new Map(map);
38	  map.delete(group);
39	}
40	
41	export function getRegisteredGroup(
42	  groupId: string
43	): RegisteredGroup | undefined;
44	export function getRegisteredGroup(
45	  groupId: string,
46	  assert: true
47	): RegisteredGroup;
48	export function getRegisteredGroup(groupId: string, assert?: boolean) {
49	  for (const [group] of map) {
50	    if (group.id === groupId) {
51	      return group;
52	    }
53	  }
54	
55	  if (assert) {
56	    throw Error(`Could not find data for Group with id ${groupId}`);
57	  }
58	
59	  return undefined;
60	}
61	
62	export function getMountedGroupState(groupId: string): State | undefined;
63	export function getMountedGroupState(groupId: string, assert: true): State;
64	export function getMountedGroupState(groupId: string, assert?: boolean) {
65	  for (const [group, mountedGroup] of map) {
66	    if (group.id === groupId) {
67	      return mountedGroup;
68	    }
69	  }
70	
71	  if (assert) {
72	    throw Error(`Could not find data for Group with id ${groupId}`);
73	  }
74	
75	  return undefined;
76	}
77	
78	export function getMountedGroups() {
79	  return map;
80	}
81	
82	export function subscribeToMountedGroup(
83	  groupId: string,
84	  callback: (event: GroupChangeEvent) => void
85	) {
86	  return eventEmitter.addListener("groupChange", (event) => {
87	    if (event.group.id === groupId) {
88	      callback(event);
89	    }
